188	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
189	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
190	        if (currentOwner != null) {
191	            Pet currentPet = this.clinicService.findPetById(petId);
192	            if (currentPet != null) {
193	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
194	                currentPet.setName(petFieldsDto.getName());
195	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
196	                this.clinicService.savePet(currentPet);
197	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
198	            }
199	        }
200	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
201	    }
