39	 * @author Rod Johnson
40	 * @author Sam Brannen
41	 * @author Michael Isvy
42	 * @author Vitaliy Fedoriv
43	 */
44	@Repository
45	@Profile("jpa")
46	public class JpaOwnerRepositoryImpl implements OwnerRepository {
47	
48	    @PersistenceContext
49	    private EntityManager em;
50	
51	
52	    /**
53	     * Important: in the current version of this method, we load Owners with all their Pets and Visits while
54	     * we do not need Visits at all and we only need one property from the Pet objects (the 'name' property).
55	     * There are some ways to improve it such as:
56	     * - creating a Ligtweight class (example here: https://community.jboss.org/wiki/LightweightClass)
57	     * - Turning on lazy-loading and using open session in view pattern
58	     */
59	    @SuppressWarnings("unchecked")
60	    public Collection<Owner> findByLastName(String lastName) {
61	        // using 'join fetch' because a single query should load both owners and pets
62	        // using 'left join fetch' because it might happen that an owner does not have pets yet
63	        Query query = this.em.createQuery("SELECT DISTINCT owner FROM Owner owner left join fetch owner.pets WHERE owner.lastName LIKE :lastName");
64	        query.setParameter("lastName", lastName + "%");
65	        return query.getResultList();
66	    }
67	
68	    @Override
69	    @SuppressWarnings("unchecked")
70	    public Page<Owner> findByLastName(String lastName, Pageable pageable) throws DataAccessException {
71	        Query query = this.em.createQuery("SELECT owner FROM Owner owner WHERE owner.lastName LIKE :lastName ORDER BY owner.id");
72	        query.setParameter("lastName", lastName + "%");
73	        query.setFirstResult((int) pageable.getOffset());
74	        query.setMaxResults(pageable.getPageSize());
75	        List<Owner> owners = query.getResultList();
76	        Query countQuery = this.em.createQuery("SELECT COUNT(owner) FROM Owner owner WHERE owner.lastName LIKE :lastName");
77	        countQuery.setParameter("lastName", lastName + "%");
78	        long total = (long) countQuery.getSingleResult();
79	        return new PageImpl<>(owners, pageable, total);
80	    }
81	
82	    @Override
83	    public Owner findById(int id) {
84	        // using 'join fetch' because a single query should load both owners and pets
85	        // using 'left join fetch' because it might happen that an owner does not have pets yet
86	        Query query = this.em.createQuery("SELECT owner FROM Owner owner left join fetch owner.pets WHERE owner.id =:id");
87	        query.setParameter("id", id);
88	        return (Owner) query.getSingleResult();
89	    }
90	
91	
92	    @Override
93	    @SuppressWarnings("unchecked")
94	    public Collection<Owner> findByTelephone(String telephone) throws DataAccessException {
95	        Query query = this.em.createQuery("SELECT owner FROM Owner owner WHERE owner.telephone = :telephone");
96	        query.setParameter("telephone", telephone);
97	        return query.getResultList();
98	    }
99	
100	    @Override
101	    public void save(Owner owner) {
102	        if (owner.getId() == null) {
103	            this.em.persist(owner);
104	        } else {
105	            this.em.merge(owner);
106	        }
107	
108	    }
109	
110		@SuppressWarnings("unchecked")
111		@Override
112		public Collection<Owner> findAll() throws DataAccessException {
113			Query query = this.em.createQuery("SELECT owner FROM Owner owner");
114	        return query.getResultList();
115		}
116	
117	    @SuppressWarnings("unchecked")
118	    @Override
119	    public Page<Owner> findAll(@NonNull Pageable pageable) throws DataAccessException {
120	        Query query = this.em.createQuery("SELECT owner FROM Owner owner ORDER BY owner.id");
121	        query.setFirstResult((int) pageable.getOffset());
122	        query.setMaxResults(pageable.getPageSize());
123	        List<Owner> owners = query.getResultList();
124	        Query countQuery = this.em.createQuery("SELECT COUNT(owner) FROM Owner owner");
125	        long total = (long) countQuery.getSingleResult();
126	        return new PageImpl<>(owners, pageable, total);
127	    }
128	
129		@Override
130		public void delete(Owner owner) throws DataAccessException {
131			this.em.remove(this.em.contains(owner) ? owner : this.em.merge(owner));
