17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
32	import org.springframework.security.access.AccessDeniedException;
33	import org.springframework.validation.BindingResult;
34	import org.springframework.web.bind.MethodArgumentNotValidException;
35	import org.springframework.web.bind.annotation.ControllerAdvice;
36	import org.springframework.web.bind.annotation.ExceptionHandler;
37	import org.springframework.web.bind.annotation.ResponseBody;
38	
39	/**
40	 * Global Exception handler for REST controllers.
41	 * <p>
42	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
43	 *
44	 * @author Vitaliy Fedoriv
45	 * @author Alexander Dudkin
46	 */
47	@ControllerAdvice
48	public class ExceptionControllerAdvice {
49	
50	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
51	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
52	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
53	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
54	
55	    /**
56	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
57	     * class.
58	     *
59	     * @param e     Object referring to the thrown exception.
60	     * @param status HTTP response status.
61	     * @param url URL request.
62	     */
63	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
64	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
65	        problemDetail.setType(URI.create(url.toString()));
66	        problemDetail.setTitle(e.getClass().getSimpleName());
67	        problemDetail.setDetail(detail);
68	        problemDetail.setProperty("timestamp", Instant.now());
69	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
70	        return problemDetail;
71	    }
72	
73	    /**
74	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
75	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
76	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
77	     * would catch it and report an authorization failure as a 500.
78	     *
79	     * @param e The {@link AccessDeniedException} to propagate
80	     * @throws AccessDeniedException always
81	     */
82	    @ExceptionHandler(AccessDeniedException.class)
83	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
84	        throw e;
85	    }
86	
87	    /**
88	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
89	     *
90	     * @param e The {@link Exception} to be handled
91	     * @param request {@link HttpServletRequest} object referring to the current request.
92	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
93	     */
94	    @ExceptionHandler(Exception.class)
95	    @ResponseBody
96	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
97	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
98	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
99	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
100	        return ResponseEntity.status(status).body(detail);
101	    }
102	
103	    /**
104	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
105	     * method returns a 404 Not Found status if an entity does not exist.
106	     *
107	     * @param e The {@link DataIntegrityViolationException} to be handled
108	     * @param request {@link HttpServletRequest} object referring to the current request.
109	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
110	     */
111	    @ExceptionHandler(DataIntegrityViolationException.class)
112	    @ResponseBody
113	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
114	        logger.warn("Data integrity violation at {} {}: {}",
115	            request.getMethod(),
116	            request.getRequestURI(),
117	            e.getMessage());
118	        logger.debug("Data integrity violation stacktrace", e);
119	        HttpStatus status = HttpStatus.NOT_FOUND;
120	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
121	        return ResponseEntity.status(status).body(detail);
122	    }
123	
124	    /**
125	     * Handles exception thrown by Bean Validation on controller methods parameters
126	     *
127	     * @param e The {@link MethodArgumentNotValidException} to be handled
128	     * @param request {@link HttpServletRequest} object referring to the current request.
129	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
130	     */
131	    @ExceptionHandler(MethodArgumentNotValidException.class)
132	    @ResponseBody
133	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
134	        HttpStatus status = HttpStatus.BAD_REQUEST;
135	        BindingResult bindingResult = e.getBindingResult();
136	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
137	        if (bindingResult.hasErrors()) {
138	            logger.debug("Validation error at {} {}: {}",
139	                request.getMethod(),
140	                request.getRequestURI(),
141	                bindingResult.getFieldErrors());
142	            detail.setProperty("schemaValidationErrors", schemaValidationErrors(bindingResult));
143	            detail.setProperty("errors", invalidFieldNames(bindingResult));
144	        }
145	        return ResponseEntity.status(status).body(detail);
146	    }
147	
148	    /**
149	     * Maps each field error of a {@link BindingResult} to a {@link ValidationMessageDto} carrying a
150	     * human-readable message plus the field name, rejected value and default message as additional
151	     * properties. Kept separate from {@link #handleMethodArgumentNotValidException} so the handler stays a
152	     * thin orchestrator and per-field details are derived in one place.
153	     *
154	     * @param bindingResult the binding result holding the field errors
155	     * @return one {@link ValidationMessageDto} per field error, in binding order
156	     */
157	    /**
158	     * Collects the distinct names of the fields that failed validation, in binding order. This is the
159	     * simple contract clients rely on to learn <em>which</em> fields were rejected (e.g. missing or blank
160	     * required fields), complementing the richer per-field {@link ValidationMessageDto} details.
161	     *
162	     * @param bindingResult the binding result holding the field errors
163	     * @return the distinct rejected field names, in binding order
164	     */
165	    private List<String> invalidFieldNames(BindingResult bindingResult) {
166	        return bindingResult.getFieldErrors().stream()
167	            .map(org.springframework.validation.FieldError::getField)
168	            .distinct()
169	            .toList();
170	    }
171	
172	    private List<ValidationMessageDto> schemaValidationErrors(BindingResult bindingResult) {
173	        return bindingResult.getFieldErrors().stream()
174	            .map(fieldError -> {
175	                String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
176	                String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
177	                String message = "Field '%s' %s (rejected value: %s)".formatted(
178	                    fieldError.getField(),
179	                    defaultMessage,
180	                    rejectedValue);
181	                return new ValidationMessageDto(message)
182	                    .putAdditionalProperty("field", fieldError.getField())
183	                    .putAdditionalProperty("rejectedValue", rejectedValue)
184	                    .putAdditionalProperty("defaultMessage", defaultMessage);
185	            })
186	            .toList();
187	    }
188	
189	}
